def summary(ch):
 title='خلاصه و نکات امتحانی '+CHAPTERS[ch]
 out=['<section class="intro"><span class="badge">مرور فصل</span><h2>'+title+'</h2><p>اول تعریف و قاعده را بخوان؛ مثال را خودت حل کن و دام امتحانی را پیش از آزمون مرور کن.</p><div class="summary-key"><span class="key-concept">تعریف و مفهوم</span><span class="key-rule">قاعدهٔ مهم</span><span class="key-example">مثال حل‌شده</span><span class="key-trap">دام امتحانی</span></div></section>']
 for i,(topic,concept,rule,example,trap) in enumerate(LESSONS[ch],1):
  out.append('<section class="summary-section"><h2>'+str(i)+'. '+topic+'</h2>')
  for cls,label,text in [('concept','تعریف روشن',concept),('rule','مهم: قاعدهٔ حل',rule),('example','مثال و مسیر حل',example),('trap','دام امتحانی',trap)]:
   out.append('<div class="study-note '+cls+'"><h3>'+label+'</h3><p data-math-text>'+escape(text)+'</p></div>')
  out.append('</section>')
 out.append('<aside class="study-note checklist"><h2>قبل از ثبت پاسخ</h2><p>شرط‌ها و واحدها را خوانده‌ام؛ علامت‌ها و پرانتزها را کنترل کرده‌ام؛ پاسخ را در صورت سؤال بررسی کرده‌ام و اگر توضیح یا رسم خواسته شده، فقط عدد ننوشته‌ام.</p></aside>')
 return ''.join(out)

def cards(ch):
 out=[]
 for topic,concept,rule,example,trap in LESSONS[ch]:
  for front,back in [('مفهوم اصلی «'+topic+'» چیست؟',concept),('قاعدهٔ کلیدی «'+topic+'» را به یاد بیاور.',rule),('یک مثال از «'+topic+'» را توضیح بده.',example),('در «'+topic+'» مراقب چه اشتباهی باشم؟',trap)]:
   out.append(dict(id=f'f{ch:02d}-card-{len(out)+1:02d}',topic=topic,front=front,back=back,chapterNumber=ch))
 for front,back in EXTRA_CARDS[ch]:out.append(dict(id=f'f{ch:02d}-card-{len(out)+1:02d}',topic=CHAPTERS[ch],front=front,back=back,chapterNumber=ch))
 return out
